import numpy as np

# Let's see what hexagonal lattices can do
# Keepout: (0.37, 0.58), r = 0.15
kx, ky, kr = 0.37, 0.58, 0.15

# Let's test a hex lattice with various spacings and rotations
best_pts = None
best_r = 0

for d in np.linspace(0.16, 0.20, 41):
    r_est = d / 2.0
    # Try different offsets and angles
    for dx in np.linspace(0, d, 15):
        for dy in np.linspace(0, d * np.sqrt(3)/2, 15):
            pts = []
            for row in range(-2, 10):
                y = r_est + dy + row * d * np.sqrt(3)/2
                if not (r_est <= y <= 1 - r_est):
                    continue
                x_offset = (row % 2) * (d / 2.0)
                for col in range(-2, 10):
                    x = r_est + dx + col * d + x_offset
                    if not (r_est <= x <= 1 - r_est):
                        continue
                    if np.hypot(x - kx, y - ky) < r_est + kr:
                        continue
                    pts.append((x, y))
            if len(pts) >= 32:
                if r_est > best_r:
                    best_r = r_est
                    best_pts = pts[:32]
                    print(f'Found {len(pts)} points with r={r_est:.4f}, sum={32*r_est:.4f}')

print('Best r:', best_r, 'Best sum:', 32 * best_r)
"

