import numpy as np

kx, ky, kr = 0.37, 0.58, 0.15
N = 32

angles = np.linspace(0, np.pi / 3, 25)
spacings = np.linspace(0.165, 0.195, 7)
count = 0
for angle in angles:
    cos_a, sin_a = np.cos(angle), np.sin(angle)
    R_mat = np.array([[cos_a, -sin_a], [sin_a, cos_a]])
    for spacing in spacings:
        dx = spacing
        dy = spacing * np.sqrt(3) / 2
        for shift_x in np.linspace(0, dx, 4, endpoint=False):
            for shift_y in np.linspace(0, dy, 4, endpoint=False):
                pts = []
                for i in range(-5, 12):
                    row_y = shift_y + i * dy
                    row_x_off = (i % 2) * (dx / 2)
                    for j in range(-5, 12):
                        px = shift_x + j * dx + row_x_off
                        py = row_y
                        p_rot = R_mat @ np.array([px - 0.5, py - 0.5]) + 0.5
                        if 0.05 <= p_rot[0] <= 0.95 and 0.05 <= p_rot[1] <= 0.95:
                            if np.hypot(p_rot[0] - kx, p_rot[1] - ky) > kr + 0.04:
                                pts.append(p_rot)
                if len(pts) >= N:
                    count += 1
print('Number of valid grids:', count)
